import React from "react";
import { motion } from "framer-motion";

const EventList = ({ darkMode }) => {
    const events = [
        {
            id: 1,
            title: "Tech Expo 2026",
            date: "May 15-17, 2026",
            location: "San Francisco, CA",
            type: "Convention",
            image: "🚀"
        },
        {
            id: 2,
            title: "Global Food Festival",
            date: "June 02, 2026",
            location: "London, UK",
            type: "Outdoor Festival",
            image: "🍕"
        },
        {
            id: 3,
            title: "Design & Creative Summit",
            date: "July 12, 2026",
            location: "Tokyo, Japan",
            type: "Workshop",
            image: "🎨"
        },
        {
            id: 4,
            title: "Sustainable Future Forum",
            date: "August 20, 2026",
            location: "Berlin, Germany",
            type: "Conference",
            image: "🌱"
        }
    ];

    return React.createElement("div", { className: "py-20 px-8 max-w-7xl mx-auto" },
        // Header
        React.createElement("div", { className: "mb-12" },
            React.createElement("h1", { className: "text-4xl font-black mb-2" }, "Upcoming Events"),
            React.createElement("p", { className: "opacity-60" }, "Explore and join world-class events managed by our team.")
        ),

        // Event Grid
        React.createElement("div", { className: "grid md:grid-cols-2 lg:grid-cols-1 gap-6" },
            events.map((event) =>
                React.createElement(motion.div, {
                    key: event.id,
                    whileHover: { x: 10 },
                    className: `p-6 rounded-3xl border flex flex-col md:flex-row items-center gap-6 ${darkMode ? "bg-gray-800 border-gray-700" : "bg-white border-gray-100 shadow-xl"
                        } transition-all`
                },
                    // Event Icon/Image Area
                    React.createElement("div", {
                        className: `w-20 h-20 rounded-2xl flex items-center justify-center text-4xl ${darkMode ? "bg-gray-700" : "bg-blue-50"
                            }`
                    }, event.image),

                    // Content Area
                    React.createElement("div", { className: "flex-grow" },
                        React.createElement("div", { className: "flex items-center gap-3 mb-1" },
                            React.createElement("span", { className: "text-xs font-bold uppercase tracking-widest text-blue-500" }, event.type),
                            React.createElement("span", { className: "text-xs opacity-40" }, "•"),
                            React.createElement("span", { className: "text-xs opacity-50 font-medium" }, event.date)
                        ),
                        React.createElement("h3", { className: "text-2xl font-bold mb-1" }, event.title),
                        React.createElement("p", { className: "opacity-60 flex items-center gap-2" },
                            React.createElement("span", null, "📍"), event.location
                        )
                    ),

                    // Action Button
                    React.createElement(motion.button, {
                        whileTap: { scale: 0.95 },
                        className: `px-8 py-3 rounded-xl font-bold transition-colors ${darkMode
                                ? "bg-blue-600 hover:bg-blue-500 text-white"
                                : "bg-gray-900 hover:bg-gray-800 text-white"
                            }`
                    }, "Register")
                )
            )
        )
    );
};

export default EventList;
